package io.github.finalparadox.entity;
import io.github.finalparadox.ability.GlaivorusAbilityState;import io.github.finalparadox.registry.ModEntities;import net.minecraft.core.particles.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.*;import net.minecraft.sounds.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;import net.minecraftforge.network.NetworkHooks;import org.joml.Vector3f;import java.util.*;
public final class RipperConeEntity extends Entity{private UUID ownerId;private Vec3 forward=Vec3.ZERO;private final Map<UUID,Integer>hitCd=new HashMap<>();public RipperConeEntity(EntityType<RipperConeEntity>t,Level l){super(t,l);noPhysics=true;noCulling=true;}public static void spawn(ServerPlayer o){RipperConeEntity e=new RipperConeEntity(ModEntities.RIPPER_CONE.get(),o.serverLevel());e.ownerId=o.getUUID();e.forward=new Vec3(o.getLookAngle().x,0,o.getLookAngle().z).normalize();if(e.forward.lengthSqr()<.01)e.forward=new Vec3(0,0,1);e.setPos(o.position());o.serverLevel().addFreshEntity(e);o.serverLevel().sendParticles(ParticleTypes.EXPLOSION,o.getX(),o.getY()-.5,o.getZ(),1,0,0,0,1);o.serverLevel().playSound(null,o.blockPosition(),SoundEvents.END_GATEWAY_SPAWN,SoundSource.PLAYERS,1,2);o.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SPEED,60,0));}
 @Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;if(!(level() instanceof ServerLevel s)){discard();return;}ServerPlayer o=ownerId==null?null:s.getServer().getPlayerList().getPlayer(ownerId);if(o==null||tickCount>10){discard();return;}hitCd.replaceAll((id,v)->v-1);hitCd.entrySet().removeIf(e->e.getValue()<=0);Vec3 side=new Vec3(-forward.z,0,forward.x);double reach=tickCount*1.2;for(int ray=0;ray<14;ray++){double angle=Math.toRadians(-36.5625+ray*5.625);Vec3 dir=forward.scale(Math.cos(angle)).add(side.scale(Math.sin(angle)));Vec3 p=position().add(dir.scale(reach));s.sendParticles(ParticleTypes.CRIT,p.x,p.y,p.z,2,.3,0,.3,.5);if(ray==0||ray==13)s.sendParticles(new DustParticleOptions(new Vector3f(1,0,0),2),p.x,p.y+.12,p.z,1,0,0,0,0);}for(LivingEntity target:s.getEntitiesOfClass(LivingEntity.class,getBoundingBox().inflate(13,3,13),e->GlaivorusAbilityState.isHostileTarget(o,e)&&!hitCd.containsKey(e.getUUID()))){Vec3 delta=target.position().subtract(position()),flat=new Vec3(delta.x,0,delta.z);double distance=flat.length();if(distance<.2||distance>reach+1.25||flat.normalize().dot(forward)<Math.cos(Math.toRadians(40)))continue;if(target.hurt(o.damageSources().playerAttack(o),30)){hitCd.put(target.getUUID(),6);target.setDeltaMovement(0,1.2,0);s.sendParticles(ParticleTypes.EXPLOSION,target.getX(),target.getY(),target.getZ(),1,0,0,0,1);}}}
 @Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Owner"))ownerId=t.getUUID("Owner");forward=new Vec3(t.getDouble("FX"),0,t.getDouble("FZ"));}@Override protected void addAdditionalSaveData(CompoundTag t){if(ownerId!=null)t.putUUID("Owner",ownerId);t.putDouble("FX",forward.x);t.putDouble("FZ",forward.z);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
